files.cart.js:
const initial = { items: [], coupon: null };

function reducer(state = initial, action) {
  switch (action.type) {
    case "add": {
      const qty = action.qty || 1;
      const existing = state.items.find((i) => i.sku === action.sku);
      if (existing) {
        existing.qty += qty;
        return { ...state, items: [...state.items] };
      }
      const item = { sku: action.sku, price: action.price, qty };
      return { ...state, items: [...state.items, item] };
    }
    case "remove":
      return { ...state, items: state.items.filter((i) => i.sku !== action.sku) };
    case "coupon":
      return { ...state, coupon: action.code };
    default:
      return state;
  }
}

function total(state) {
  let sum = 0;
  for (const item of state.items) {
    sum += item.price * item.qty;
  }
  if (state.coupon === "SAVE10") {
    sum = sum * 0.9;
  }
  return sum;
}

module.exports = { reducer, total, initial };

