const assert = require("assert");
const { reducer, total } = require("./cart.js");

const add = (sku, price, qty) => ({ type: "add", sku, price, qty });

module.exports = {
  "adds a new item": () => {
    const s = reducer(undefined, add("a", 5, 2));
    assert.deepStrictEqual(s.items, [{ sku: "a", price: 5, qty: 2 }], "new item should be appended with its qty");
  },
  "adding an existing sku increases its quantity": () => {
    let s = reducer(undefined, add("a", 5, 1));
    s = reducer(s, add("a", 5, 2));
    assert.strictEqual(s.items.length, 1, "same sku must not create a second line");
    assert.strictEqual(s.items[0].qty, 3, "quantity should be 3");
  },
  "reducer does not mutate the previous state": () => {
    const s1 = reducer(undefined, add("a", 5, 1));
    const s2 = reducer(s1, add("a", 5, 2));
    assert.strictEqual(s1.items[0].qty, 1, "previous state was mutated (qty changed to " + s1.items[0].qty + ")");
    assert.strictEqual(s2.items[0].qty, 3, "new state should have qty 3");
    assert.notStrictEqual(s1.items[0], s2.items[0], "changed line items must be new objects");
  },
  "removes an item by sku": () => {
    let s = reducer(undefined, add("a", 5, 1));
    s = reducer(s, add("b", 7, 1));
    s = reducer(s, { type: "remove", sku: "a" });
    assert.deepStrictEqual(s.items.map((i) => i.sku), ["b"]);
  },
  "total does not show floating point drift": () => {
    let s = reducer(undefined, add("a", 0.1, 1));
    s = reducer(s, add("b", 0.2, 1));
    assert.strictEqual(total(s), 0.3, "0.1 + 0.2 should total exactly 0.3, got " + total(s));
  },
  "coupon takes 10 percent off rounded to a whole cent": () => {
    let s = reducer(undefined, add("a", 19.99, 1));
    s = reducer(s, { type: "coupon", code: "SAVE10" });
    assert.strictEqual(total(s), 17.99, "19.99 with SAVE10 should be 17.99, got " + total(s));
  },
  "unknown actions return the same state object": () => {
    const s = reducer(undefined, add("a", 1, 1));
    assert.strictEqual(reducer(s, { type: "nope" }), s);
  },
};

solution.cart.js:
const initial = { items: [], coupon: null };

function reducer(state = initial, action) {
  switch (action.type) {
    case "add": {
      const qty = action.qty || 1;
      const exists = state.items.some((i) => i.sku === action.sku);
      if (exists) {
        const items = state.items.map((i) => (i.sku === action.sku ? { ...i, qty: i.qty + qty } : i));
        return { ...state, items };
      }
      const item = { sku: action.sku, price: action.price, qty };
      return { ...state, items: [...state.items, item] };
    }
    case "remove":
      return { ...state, items: state.items.filter((i) => i.sku !== action.sku) };
    case "coupon":
      return { ...state, coupon: action.code };
    default:
      return state;
  }
}

function toCents(amount) {
  return Math.round(amount * 100);
}

function total(state) {
  let cents = 0;
  for (const item of state.items) {
    cents += toCents(item.price) * item.qty;
  }
  if (state.coupon === "SAVE10") {
    cents = Math.round(cents * 0.9);
  }
  return cents / 100;
}

module.exports = { reducer, total, initial };

