function paginate(items, page = 1, perPage = 10) {
  const totalPages = Math.floor(items.length / perPage);
  const start = page * perPage;
  const slice = items.slice(start, start + perPage);
  return {
    items: slice,
    page,
    perPage,
    total: items.length,
    totalPages,
    hasNext: page < totalPages,
    hasPrev: page > 1,
  };
}

module.exports = { paginate };

files.labels.js:
function describeRange(p) {
  if (p.total === 0) return "No results";
  const first = (p.page - 1) * p.perPage + 1;
  const last = Math.min(p.page * p.perPage, p.total);
  return "Showing " + first + "-" + last + " of " + p.total;
}

function pageWindow(current, totalPages, size = 5) {
  const half = Math.floor(size / 2);
  let from = Math.max(1, current - half);
  let to = Math.min(totalPages, from + size - 1);
  from = Math.max(1, to - size + 1);
  const out = [];
  for (let n = from; n <= to; n++) out.push(n);
  return out;
}

module.exports = { describeRange, pageWindow };

