  },
  "last partial page returns the remainder": () => {
    const p = paginate(nums(25), 3, 10);
    assert.deepStrictEqual(p.items, [21, 22, 23, 24, 25]);
  },
  "total pages rounds up": () => {
    assert.strictEqual(paginate(nums(25), 1, 10).totalPages, 3, "25 items at 10 per page is 3 pages");
  },
  "exact multiple does not add an extra page": () => {
    assert.strictEqual(paginate(nums(20), 1, 10).totalPages, 2);
  },
  "hasNext and hasPrev flags": () => {
    assert.strictEqual(paginate(nums(25), 2, 10).hasNext, true, "page 2 of 3 has a next page");
    assert.strictEqual(paginate(nums(25), 3, 10).hasNext, false, "page 3 of 3 has no next page");
    assert.strictEqual(paginate(nums(25), 1, 10).hasPrev, false);
  },
  "empty list has zero pages": () => {
    const p = paginate([], 1, 10);
    assert.strictEqual(p.totalPages, 0);
    assert.strictEqual(p.hasNext, false);
    assert.strictEqual(describeRange(p), "No results");
  },
  "labels describe the visible range": () => {
    assert.strictEqual(describeRange(paginate(nums(25), 3, 10)), "Showing 21-25 of 25");
    assert.deepStrictEqual(pageWindow(1, 3), [1, 2, 3]);
    assert.deepStrictEqual(pageWindow(9, 12), [7, 8, 9, 10, 11]);
  },
};

