function buildQuery(params) {
  const parts = [];
  for (const key of Object.keys(params)) {
    const value = params[key];
    if (!value) continue;
    if (Array.isArray(value)) {
      for (const v of value) parts.push(key + "=" + v);
    } else {
      parts.push(key + "=" + value);
    }
  }
  return parts.length ? "?" + parts.join("&") : "";
}

function parseQuery(qs) {
  const out = {};
  const s = qs.startsWith("?") ? qs.slice(1) : qs;
  if (!s) return out;
  for (const pair of s.split("&")) {
    const idx = pair.indexOf("=");
    const key = decodeURIComponent(idx === -1 ? pair : pair.slice(0, idx));
    const value = idx === -1 ? "" : decodeURIComponent(pair.slice(idx + 1));
    if (Object.prototype.hasOwnProperty.call(out, key)) {
      out[key] = [].concat(out[key], value);
    } else {
      out[key] = value;
    }
  }
  return out;
}

module.exports = { buildQuery, parseQuery };

