const isEmpty = (v) => v == "" || v == null;

const rules = {
  required: () => (v) => (isEmpty(v) ? "is required" : null),
  min: (n) => (v) => (v < n ? "must be at least " + n : null),
  max: (n) => (v) => (v > n ? "must be at most " + n : null),
  email: () => (v) => (/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v) ? null : "must be a valid email"),
};

function validate(schema, data) {
  const errors = {};
  for (const field of Object.keys(schema)) {
    const value = data[field];
    for (const rule of schema[field]) {
      const [name, arg] = Array.isArray(rule) ? rule : [rule];
      if (name !== "required" && isEmpty(value)) continue;
      const message = rules[name](arg)(value);
      if (message) {
        errors[field] = field + " " + message;
        break;
      }
    }
  }
  return { valid: Object.keys(errors).length === 0, errors };
}

module.exports = { validate };

