const assert = require("assert");
const { rank, topN, positionOf } = require("./leaderboard.js");

const sample = () => [
  { name: "dina", score: 50 },
  { name: "bo", score: 90 },
  { name: "eli", score: 70 },
  { name: "al", score: 70 },
  { name: "cy", score: 10 },
  { name: "fay", score: 90 },
];

module.exports = {
  "sorts by score descending": () => {
    const scores = rank(sample()).map((p) => p.score);
    assert.deepStrictEqual(scores, [90, 90, 70, 70, 50, 10], "got " + JSON.stringify(scores));
  },
  "ties share a rank and the next rank skips": () => {
    const ranks = rank(sample()).map((p) => p.rank);
    assert.deepStrictEqual(ranks, [1, 1, 3, 3, 5, 6], "got " + JSON.stringify(ranks));
  },
  "ties are ordered by name": () => {
    const names = rank(sample()).map((p) => p.name);
    assert.deepStrictEqual(names, ["bo", "fay", "al", "eli", "dina", "cy"]);
  },
  "does not reorder or modify the input": () => {
    const input = sample();
    rank(input);
    assert.deepStrictEqual(input.map((p) => p.name), ["dina", "bo", "eli", "al", "cy", "fay"], "input array was re-sorted");
    assert.strictEqual("rank" in input[0], false, "input objects must not gain a rank");
  },
  "topN keeps everyone tied at the boundary": () => {
    assert.deepStrictEqual(topN(sample(), 3).map((p) => p.name), ["bo", "fay", "al", "eli"]);
  },
  "positionOf finds a player or null": () => {
    assert.strictEqual(positionOf(sample(), "eli"), 3);
    assert.strictEqual(positionOf(sample(), "zed"), null);
  },
  "empty and single player lists": () => {
    assert.deepStrictEqual(rank([]), []);
    assert.deepStrictEqual(rank([{ name: "x", score: 0 }]), [{ name: "x", score: 0, rank: 1 }]);
  },
};

solution.leaderboard.js:
function rank(players) {
  const sorted = [...players].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));
  let prevScore = null;
  let prevRank = 0;
  return sorted.map((p, i) => {
    const r = p.score === prevScore ? prevRank : i + 1;
    prevScore = p.score;
    prevRank = r;
    return { ...p, rank: r };
  });
}

function topN(players, n) {
  return rank(players).filter((p) => p.rank <= n);
}

function positionOf(players, name) {
  const row = rank(players).find((p) => p.name === name);
  return row ? row.rank : null;
}

module.exports = { rank, topN, positionOf };

files.debounce.js:
function debounce(fn, wait, timers = { setTimeout, clearTimeout }) {
  let timer = null;

  function debounced(...args) {
    timer = timers.setTimeout(() => {
      timer = null;
      fn(...args);
    }, wait);
  }

  debounced.cancel = () => {
    if (timer !== null) timers.clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

module.exports = { debounce };

files.throttle.js:
function throttle(fn, wait, now = Date.now) {
  let last = 0;

  return function throttled(...args) {
    const t = now();
    if (t - last > wait) {
      last = t;
      return fn.apply(this, args);
    }
    return undefined;
  };
}

module.exports = { throttle };

