const assert = require("assert");
const { debounce } = require("./debounce.js");
const { throttle } = require("./throttle.js");

function fakeTimers() {
  let now = 0;
  let id = 0;
  const pending = new Map();
  return {
    now: () => now,
    setTimeout(fn, ms) {
      const t = ++id;
      pending.set(t, { fn, at: now + ms });
      return t;
    },
    clearTimeout(t) {
      pending.delete(t);
    },
    advance(ms) {
      const end = now + ms;
      for (;;) {
        let next = null;
        for (const [t, e] of pending) {
          if (e.at <= end && (!next || e.at < next.e.at)) next = { t, e };
        }
        if (!next) break;
        pending.delete(next.t);
        now = next.e.at;
        next.e.fn();
      }
      now = end;
    },
  };
}

module.exports = {
  "debounce collapses a burst into one call with the last arguments": () => {
    const clock = fakeTimers();
    const calls = [];
    const d = debounce((x) => calls.push(x), 100, clock);
    d("a");
    d("b");
    d("c");
    clock.advance(100);
    assert.deepStrictEqual(calls, ["c"], "expected one call with the last args, got " + JSON.stringify(calls));
  },
  "debounce restarts the wait on every call": () => {
    const clock = fakeTimers();
    let n = 0;
    const d = debounce(() => n++, 100, clock);
    d();
    clock.advance(60);
    d();
    clock.advance(60);
    assert.strictEqual(n, 0, "only 60ms passed since the last call");
    clock.advance(40);
    assert.strictEqual(n, 1);
  },
  "debounce preserves this": () => {
    const clock = fakeTimers();
    const obj = { name: "box", seen: null };
    obj.run = debounce(function () {
      this.seen = this.name;
    }, 10, clock);
    obj.run();
    clock.advance(10);
    assert.strictEqual(obj.seen, "box", "this was not forwarded to the wrapped function");
  },
  "debounce cancel prevents the call": () => {
    const clock = fakeTimers();
    let n = 0;
    const d = debounce(() => n++, 50, clock);
    d();
    d.cancel();
    clock.advance(100);
    assert.strictEqual(n, 0);
  },
  "throttle runs the first call immediately even at time zero": () => {
    const clock = fakeTimers();
    const calls = [];
    const t = throttle((x) => calls.push(x), 100, clock.now);
    t("first");
    assert.deepStrictEqual(calls, ["first"], "first call must not be throttled");
  },
  "throttle drops calls inside the window": () => {
    const clock = fakeTimers();
    const calls = [];
    const t = throttle((x) => calls.push(x), 100, clock.now);
    t(1);
    clock.advance(50);
    t(2);
    clock.advance(49);
    t(3);
    assert.deepStrictEqual(calls, [1]);
  },
  "throttle allows a call exactly one interval later": () => {
    const clock = fakeTimers();
    const calls = [];
    const t = throttle((x) => calls.push(x), 100, clock.now);
    clock.advance(1000);
    t("a");
    clock.advance(100);
    t("b");
    assert.deepStrictEqual(calls, ["a", "b"], "a call at exactly t+wait should go through");
  },
  "throttle returns the value and keeps this": () => {
    const clock = fakeTimers();
    const o = { k: 7, get: throttle(function () { return this.k; }, 10, clock.now) };
    assert.strictEqual(o.get(), 7);
  },
};

solution.debounce.js:
function debounce(fn, wait, timers = { setTimeout, clearTimeout }) {
  let timer = null;

  function debounced(...args) {
    if (timer !== null) timers.clearTimeout(timer);
    const ctx = this;
    timer = timers.setTimeout(() => {
      timer = null;
      fn.apply(ctx, args);
    }, wait);
  }

  debounced.cancel = () => {
    if (timer !== null) timers.clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

module.exports = { debounce };

solution.throttle.js:
function throttle(fn, wait, now = Date.now) {
  let last = -Infinity;

  return function throttled(...args) {
    const t = now();
    if (t - last >= wait) {
      last = t;
      return fn.apply(this, args);
    }
    return undefined;
  };
}

module.exports = { throttle };

