async function pool(tasks, limit) {
  const results = [];
  let next = 0;

  async function worker() {
    while (next < tasks.length) {
      const task = tasks[next++];
      const value = await task();
      results.push(value);
    }
  }

  const workers = [];
  for (let i = 0; i <= limit; i++) {
