const assert = require("assert");
const { retry } = require("./retry.js");
const { callGateway } = require("./gateway.js");

function flaky(failures, err = new Error("boom")) {
  let calls = 0;
  const fn = async () => {
    calls++;
    if (calls <= failures) throw err;
    return "ok";
  };
  fn.calls = () => calls;
  return fn;
}

function recorder() {
  const delays = [];
  return { delays, sleep: async (ms) => { delays.push(ms); } };
}

module.exports = {
  "returns immediately on success without sleeping": async () => {
    const r = recorder();
    const fn = flaky(0);
    assert.strictEqual(await retry(fn, { sleep: r.sleep }), "ok");
    assert.deepStrictEqual(r.delays, []);
  },
  "retries an async failure and then succeeds": async () => {
    const r = recorder();
    const fn = flaky(2);
    const result = await retry(fn, { retries: 3, sleep: r.sleep });
    assert.strictEqual(result, "ok");
    assert.strictEqual(fn.calls(), 3);
  },
  "waits with exponential backoff": async () => {
    const r = recorder();
    await retry(flaky(3), { retries: 3, baseMs: 100, sleep: r.sleep });
    assert.deepStrictEqual(r.delays, [100, 200, 400], "got delays " + JSON.stringify(r.delays));
  },
  "makes retries + 1 attempts then throws the last error": async () => {
    const r = recorder();
    const err = new Error("still down");
    const fn = flaky(99, err);
    await assert.rejects(() => retry(fn, { retries: 2, sleep: r.sleep }), (e) => e === err);
    assert.strictEqual(fn.calls(), 3, "1 initial attempt + 2 retries = 3 calls, got " + fn.calls());
    assert.deepStrictEqual(r.delays, [100, 200], "no sleep after the final failure");
  },
  "shouldRetry can stop retrying early": async () => {
    const r = recorder();
    const fn = flaky(5, Object.assign(new Error("bad request"), { status: 400 }));
    await assert.rejects(() => retry(fn, { sleep: r.sleep, shouldRetry: (e) => e.status !== 400 }));
    assert.strictEqual(fn.calls(), 1);
  },
  "handles functions that throw synchronously": async () => {
    let calls = 0;
    const r = recorder();
    const result = await retry(() => {
      calls++;
      if (calls < 2) throw new Error("sync");
      return "fine";
    }, { sleep: r.sleep });
    assert.strictEqual(result, "fine");
  },
  "passes the attempt number to fn": async () => {
    const seen = [];
    await retry(async (n) => { seen.push(n); if (n < 2) throw new Error("x"); }, { sleep: async () => {} });
    assert.deepStrictEqual(seen, [0, 1, 2]);
  },
  "gateway retries 5xx but not 4xx": async () => {
    const r = recorder();
    let n = 0;
    const client = { send: async () => { n++; if (n < 3) throw Object.assign(new Error("gw"), { status: 503 }); return { ok: true }; } };
    assert.deepStrictEqual(await callGateway(client, {}, { sleep: r.sleep }), { ok: true });
    let m = 0;
    const bad = { send: async () => { m++; throw Object.assign(new Error("nope"), { status: 404 }); } };
    await assert.rejects(() => callGateway(bad, {}, { sleep: r.sleep }));
    assert.strictEqual(m, 1, "404 must not be retried");
  },
