class TTLCache {
  constructor({ ttl = 1000, now = Date.now } = {}) {
    this.ttl = ttl;
    this.now = now;
    this.store = new Map();
  }

  _expired(entry) {
    return entry.expires <= this.now();
  }

  _live(key) {
    const entry = this.store.get(key);
    if (!entry) return null;
    if (this._expired(entry)) {
      this.store.delete(key);
      return null;
    }
    return entry;
  }

  set(key, value, ttl = this.ttl) {
    this.store.set(key, { value, expires: this.now() + ttl });
    return this;
  }

  get(key) {
    const entry = this._live(key);
    return entry ? entry.value : undefined;
  }

  has(key) {
    return this._live(key) !== null;
  }

  delete(key) {
    return this.store.delete(key);
  }

  purge() {
    for (const [key, entry] of this.store) {
      if (this._expired(entry)) this.store.delete(key);
    }
  }

  get size() {
    this.purge();
    return this.store.size;
  }

  async getOrSet(key, loader, ttl) {
    if (this.has(key)) return this.get(key);
    const value = await loader();
    this.set(key, value, ttl);
    return value;
  }
}

module.exports = { TTLCache };

