const { toCents, formatCents, splitCents } = require("./money.js");

function lineTotal(unitPrice, qty, discountPct = 0) {
  const gross = toCents(unitPrice) * qty;
  return Math.round((gross * (100 - discountPct)) / 100);
}

function invoiceSummary(lines, taxRate) {
  const subtotal = lines.reduce((sum, l) => sum + lineTotal(l.price, l.qty, l.discount), 0);
  const tax = Math.round(subtotal * taxRate);
  const total = subtotal + tax;
  return { subtotal, tax, total, display: formatCents(total) };
}

function splitBill(totalCents, names) {
  const shares = splitCents(totalCents, names.length);
  return Object.fromEntries(names.map((name, i) => [name, shares[i]]));
}

module.exports = { lineTotal, invoiceSummary, splitBill };

