function toCents(amount) {
  return Math.round(amount * 100);
}

function formatCents(cents, symbol = "$") {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const dollars = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  const rest = String(abs % 100).padStart(2, "0");
  return sign + symbol + dollars + "." + rest;
}

function splitCents(total, parts) {
  const base = Math.floor(total / parts);
  const remainder = total - base * parts;
  return Array.from({ length: parts }, (_, i) => base + (i < remainder ? 1 : 0));
}

module.exports = { toCents, formatCents, splitCents };

files.todoStore.js:
class TodoStore {
  constructor() {
    this.todos = [];
    this.past = [];
    this.future = [];
    this.nextId = 1;
  }

  _snapshot() {
    this.past.push(this.todos.slice());
  }

  _find(id) {
    return this.todos.find((t) => t.id === id);
  }

  add(text) {
    this._snapshot();
    const todo = { id: this.nextId++, text, done: false };
    this.todos.push(todo);
    return todo.id;
  }

  toggle(id) {
    this._snapshot();
    const todo = this._find(id);
    todo.done = !todo.done;
    return true;
  }

  remove(id) {
    this._snapshot();
    this.todos = this.todos.filter((t) => t.id !== id);
    return true;
  }

  undo() {
    if (this.past.length === 0) return false;
    this.future.push(this.todos);
    this.todos = this.past.pop();
    return true;
  }

  redo() {
    if (this.future.length === 0) return false;
    this.past.push(this.todos);
    this.todos = this.future.pop();
    return true;
  }

  get canUndo() {
    return this.past.length > 0;
  }

  get canRedo() {
    return this.future.length > 0;
  }
}

module.exports = { TodoStore };

