const { TodoStore } = require("./todoStore.js");
const { stats } = require("./stats.js");

const texts = (s) => s.todos.map((t) => t.text);

module.exports = {
  "add then undo then redo": () => {
    const s = new TodoStore();
    s.add("a");
    s.add("b");
    assert.deepStrictEqual(texts(s), ["a", "b"]);
    s.undo();
    assert.deepStrictEqual(texts(s), ["a"]);
    s.redo();
    assert.deepStrictEqual(texts(s), ["a", "b"]);
  },
  "undo of a toggle restores the previous done flag": () => {
    const s = new TodoStore();
    const id = s.add("a");
    s.toggle(id);
    assert.strictEqual(s.todos[0].done, true);
    s.undo();
    assert.strictEqual(s.todos[0].done, false, "undo did not restore done = false");
  },
  "redo of a toggle re-applies it": () => {
    const s = new TodoStore();
    const id = s.add("a");
    s.toggle(id);
    s.undo();
    s.redo();
    assert.strictEqual(s.todos[0].done, true);
  },
  "a new action clears the redo history": () => {
    const s = new TodoStore();
    s.add("a");
    s.add("b");
    s.undo();
    s.add("c");
    assert.strictEqual(s.canRedo, false, "redo should be unavailable after a new edit");
    assert.strictEqual(s.redo(), false);
    assert.deepStrictEqual(texts(s), ["a", "c"]);
  },
  "toggling or removing a missing id is a no-op": () => {
    const s = new TodoStore();
    s.add("a");
    assert.strictEqual(s.toggle(999), false, "toggle of a missing id should return false, not throw");
    assert.strictEqual(s.remove(999), false);
    s.undo();
    assert.deepStrictEqual(texts(s), [], "undo should revert the add, not a phantom entry");
  },
  "undo of remove brings the item back": () => {
    const s = new TodoStore();
    const id = s.add("a");
    s.add("b");
    s.remove(id);
    assert.deepStrictEqual(texts(s), ["b"]);
    s.undo();
    assert.deepStrictEqual(texts(s), ["a", "b"]);
  },
  "undo on an empty history returns false": () => {
    const s = new TodoStore();
    assert.strictEqual(s.undo(), false);
    assert.strictEqual(s.canUndo, false);
  },
  "stats summarise completion": () => {
    const s = new TodoStore();
    const a = s.add("a");
    s.add("b");
    s.add("c");
    s.toggle(a);
    assert.deepStrictEqual(stats(s.todos), { total: 3, done: 1, remaining: 2, percent: 33 });
  },
};

solution.todoStore.js:
class TodoStore {
  constructor() {
    this.todos = [];
    this.past = [];
    this.future = [];
    this.nextId = 1;
  }

  _commit() {
    this.past.push(this.todos.map((t) => ({ ...t })));
    this.future = [];
  }

  _find(id) {
    return this.todos.find((t) => t.id === id);
  }

  add(text) {
    this._commit();
    const todo = { id: this.nextId++, text, done: false };
    this.todos.push(todo);
    return todo.id;
  }

  toggle(id) {
    const todo = this._find(id);
    if (!todo) return false;
    this._commit();
    todo.done = !todo.done;
    return true;
  }

  remove(id) {
    if (!this._find(id)) return false;
    this._commit();
    this.todos = this.todos.filter((t) => t.id !== id);
    return true;
  }

  undo() {
    if (this.past.length === 0) return false;
    this.future.push(this.todos);
    this.todos = this.past.pop();
    return true;
  }

  redo() {
    if (this.future.length === 0) return false;
    this.past.push(this.todos);
    this.todos = this.future.pop();
    return true;
  }

  get canUndo() {
    return this.past.length > 0;
  }

  get canRedo() {
    return this.future.length > 0;
  }
}

module.exports = { TodoStore };

files.compose.js:
function compose(middleware) {
  return function run(ctx, finalHandler) {
    let index = -1;

    function dispatch(i) {
      if (i < index) {
        return Promise.reject(new Error("next() called multiple times"));
      }
      index = i;
      let fn = middleware[i];
      if (i === middleware.length) fn = finalHandler;
      if (!fn) return Promise.resolve();
      try {
        return Promise.resolve(fn(ctx, () => dispatch(i + 1)));
      } catch (err) {
        return Promise.reject(err);
      }
    }

    return dispatch(0);
  };
}

module.exports = { compose };

files.middlewares.js:
function logger(lines) {
  return async (ctx, next) => {
    lines.push("-> " + ctx.path);
    await next();
    lines.push("<- " + ctx.path + " " + (ctx.status || 200));
  };
}

function timing(now = Date.now) {
  return async (ctx, next) => {
    const start = now();
    next();
    ctx.elapsed = now() - start;
  };
}

function errorBoundary(onError) {
  return async (ctx, next) => {
    try {
      return next();
    } catch (err) {
      ctx.status = 500;
      onError(err);
    }
  };
}

module.exports = { logger, timing, errorBoundary };

