const assert = require("assert");
const { compose } = require("./compose.js");
const { logger, timing, errorBoundary } = require("./middlewares.js");

const tick = () => new Promise((r) => setTimeout(r, 1));

module.exports = {
  "runs middleware in onion order": async () => {
    const log = [];
    const mk = (name) => async (ctx, next) => {
      log.push(name + ":in");
      await tick();
      await next();
      log.push(name + ":out");
    };
    await compose([mk("a"), mk("b")])({}, async () => { log.push("handler"); });
    assert.deepStrictEqual(log, ["a:in", "b:in", "handler", "b:out", "a:out"]);
  },
  "middleware can short circuit": async () => {
    let reached = false;
    const deny = async (ctx) => { ctx.status = 401; };
    const ctx = {};
    await compose([deny])(ctx, async () => { reached = true; });
    assert.strictEqual(ctx.status, 401);
    assert.strictEqual(reached, false);
  },
  "calling next twice rejects": async () => {
    let handlerRuns = 0;
    const twice = async (ctx, next) => {
      await next();
      await next();
    };
    await assert.rejects(
      () => compose([twice])({}, async () => { handlerRuns++; }),
      /multiple times/,
      "a second next() must reject"
    );
    assert.strictEqual(handlerRuns, 1, "handler ran " + handlerRuns + " times");
  },
  "synchronous throws become rejections": async () => {
    const boom = () => { throw new Error("sync boom"); };
    await assert.rejects(() => compose([boom])({}, async () => {}), /sync boom/);
  },
  "errorBoundary catches async errors from downstream": async () => {
    const seen = [];
    const ctx = {};
    const handler = async () => {
      await tick();
      throw new Error("db down");
    };
    await compose([errorBoundary((e) => seen.push(e.message))])(ctx, handler);
    assert.deepStrictEqual(seen, ["db down"], "error handler was not called");
    assert.strictEqual(ctx.status, 500);
  },
  "errorBoundary lets normal requests through": async () => {
    const ctx = {};
    await compose([errorBoundary(() => assert.fail("no error expected"))])(ctx, async () => { ctx.body = "ok"; });
    assert.strictEqual(ctx.body, "ok");
    assert.strictEqual(ctx.status, undefined);
  },
  "timing measures the downstream work": async () => {
    const clock = { t: 1000 };
    const ctx = {};
    await compose([timing(() => clock.t)])(ctx, async () => {
      await tick();
      clock.t += 50;
    });
    assert.strictEqual(ctx.elapsed, 50, "elapsed was " + ctx.elapsed);
  },
  "logger wraps the whole request": async () => {
    const lines = [];
    const ctx = { path: "/pay" };
    await compose([logger(lines), errorBoundary(() => {})])(ctx, async () => { await tick(); throw new Error("x"); });
    assert.deepStrictEqual(lines, ["-> /pay", "<- /pay 500"]);
  },
};

