files.dates.js:
const DAY = 24 * 60 * 60 * 1000;

function pad(n) {
  return String(n).padStart(2, "0");
}

function formatDate(d) {
  return d.getUTCFullYear() + "-" + pad(d.getUTCMonth() + 1) + "-" + pad(d.getUTCDate());
}

function parseDate(s) {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}

function addDays(d, n) {
  d.setUTCDate(d.getUTCDate() + n);
  return d;
}

function addMonths(d, n) {
  const r = new Date(d.getTime());
  r.setUTCMonth(r.getUTCMonth() + n);
  return r;
}

function daysBetween(a, b) {
  return Math.round((b - a) / DAY);
}

module.exports = { formatDate, parseDate, addDays, addMonths, daysBetween };

files.schedule.js:
const { addDays, addMonths, daysBetween } = require("./dates.js");

function billingDates(start, count) {
  const out = [];
  let current = start;
  for (let i = 0; i < count; i++) {
    out.push(current);
    current = addMonths(current, 1);
  }
  return out;
}

function trialEnd(start, trialDays) {
  return addDays(start, trialDays);
}

function nextBillingDate(start, today) {
  let i = 0;
  let date = start;
  while (date <= today) {
    i++;
    date = addMonths(start, i);
  }
  return date;
}

function daysUntilNextBill(start, today) {
  return daysBetween(today, nextBillingDate(start, today));
}

module.exports = { billingDates, trialEnd, nextBillingDate, daysUntilNextBill };

