const assert = require("assert");
const { formatDate, parseDate, addDays, addMonths, daysBetween } = require("./dates.js");
const { billingDates, trialEnd, nextBillingDate, daysUntilNextBill } = require("./schedule.js");

const D = parseDate;
const F = formatDate;

module.exports = {
  "parse and format round trip": () => {
    assert.strictEqual(F(D("2024-03-05")), "2024-03-05");
    assert.strictEqual(F(D("1999-12-31")), "1999-12-31");
  },
  "addDays crosses month and leap boundaries": () => {
    assert.strictEqual(F(addDays(D("2024-02-28"), 2)), "2024-03-01");
    assert.strictEqual(F(addDays(D("2023-02-28"), 2)), "2023-03-02");
    assert.strictEqual(F(addDays(D("2024-01-01"), -1)), "2023-12-31");
  },
  "addDays does not mutate its input": () => {
    const d = D("2024-01-30");
    const e = addDays(d, 5);
    assert.strictEqual(F(d), "2024-01-30", "input date was changed to " + F(d));
    assert.strictEqual(F(e), "2024-02-04");
  },
  "addMonths clamps to the end of a shorter month": () => {
    assert.strictEqual(F(addMonths(D("2024-01-31"), 1)), "2024-02-29");
    assert.strictEqual(F(addMonths(D("2023-01-31"), 1)), "2023-02-28");
    assert.strictEqual(F(addMonths(D("2024-03-31"), -1)), "2024-02-29");
    assert.strictEqual(F(addMonths(D("2024-05-31"), 1)), "2024-06-30");
  },
  "addMonths handles year rollover": () => {
    assert.strictEqual(F(addMonths(D("2024-12-15"), 2)), "2025-02-15");
    assert.strictEqual(F(addMonths(D("2024-01-15"), -2)), "2023-11-15");
    assert.strictEqual(F(addMonths(D("2024-01-15"), 24)), "2026-01-15");
  },
  "billing dates stay anchored to the original day": () => {
    const dates = billingDates(D("2024-01-31"), 5).map(F);
    assert.deepStrictEqual(dates, ["2024-01-31", "2024-02-29", "2024-03-31", "2024-04-30", "2024-05-31"], "got " + dates.join(","));
  },
  "trialEnd leaves the start date untouched": () => {
    const start = D("2024-06-01");
    const end = trialEnd(start, 14);
    assert.strictEqual(F(end), "2024-06-15");
    assert.strictEqual(F(start), "2024-06-01", "trialEnd mutated the subscription start");
  },
  "next billing date and countdown": () => {
    const start = D("2024-01-31");
    assert.strictEqual(F(nextBillingDate(start, D("2024-02-10"))), "2024-02-29");
    assert.strictEqual(F(nextBillingDate(start, D("2024-02-29"))), "2024-03-31");
    assert.strictEqual(daysUntilNextBill(start, D("2024-03-01")), 30);
    assert.strictEqual(daysBetween(D("2024-01-01"), D("2024-03-01")), 60);
  },
};

solution.dates.js:
const DAY = 24 * 60 * 60 * 1000;

function pad(n) {
  return String(n).padStart(2, "0");
}

function formatDate(d) {
  return d.getUTCFullYear() + "-" + pad(d.getUTCMonth() + 1) + "-" + pad(d.getUTCDate());
}

function parseDate(s) {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}

function addDays(d, n) {
  const r = new Date(d.getTime());
  r.setUTCDate(r.getUTCDate() + n);
  return r;
}

function addMonths(d, n) {
  const r = new Date(d.getTime());
  const day = r.getUTCDate();
  r.setUTCDate(1);
  r.setUTCMonth(r.getUTCMonth() + n);
  const lastDay = new Date(Date.UTC(r.getUTCFullYear(), r.getUTCMonth() + 1, 0)).getUTCDate();
  r.setUTCDate(Math.min(day, lastDay));
  return r;
}

function daysBetween(a, b) {
  return Math.round((b - a) / DAY);
}

module.exports = { formatDate, parseDate, addDays, addMonths, daysBetween };

