const assert = require("assert");
const { deepMerge } = require("./merge.js");
const { DEFAULTS, resolveConfig } = require("./config.js");

module.exports = {
  "merges nested objects recursively": () => {
    const out = deepMerge({ a: { x: 1, y: 2 }, b: 1 }, { a: { y: 3, z: 4 }, c: 5 });
    assert.deepStrictEqual(out, { a: { x: 1, y: 3, z: 4 }, b: 1, c: 5 });
  },
  "later sources win": () => {
    assert.deepStrictEqual(deepMerge({ a: 1 }, { a: 2 }, { a: 3 }), { a: 3 });
  },
  "does not mutate its inputs": () => {
    const a = { n: { x: 1 } };
    const b = { n: { y: 2 } };
    const out = deepMerge(a, b);
    assert.deepStrictEqual(a, { n: { x: 1 } }, "first argument was modified: " + JSON.stringify(a));
    assert.deepStrictEqual(b, { n: { y: 2 } });
    assert.deepStrictEqual(out, { n: { x: 1, y: 2 } });
  },
  "result does not share nested objects with the inputs": () => {
    const b = { n: { y: 2 } };
    const out = deepMerge({}, b);
    out.n.y = 99;
    assert.strictEqual(b.n.y, 2, "nested object is aliased to the source");
  },
  "arrays are replaced, not merged by index": () => {
    const out = deepMerge({ tags: ["a", "b", "c"] }, { tags: ["x"] });
    assert.deepStrictEqual(out.tags, ["x"], "got " + JSON.stringify(out.tags));
  },
  "null overrides an object value": () => {
    const out = deepMerge({ cache: { ttl: 60 } }, { cache: null });
    assert.deepStrictEqual(out, { cache: null });
  },
  "resolveConfig leaves the shared defaults untouched": () => {
    const first = resolveConfig({ db: { port: 6543, options: { ssl: true } } });
    assert.strictEqual(first.db.port, 6543);
    assert.strictEqual(first.db.host, "localhost");
    const second = resolveConfig();
    assert.strictEqual(second.db.port, 5432, "defaults leaked from a previous call");
    assert.strictEqual(DEFAULTS.db.options.ssl, false, "DEFAULTS were modified");
    assert.deepStrictEqual(DEFAULTS.allowedHosts, ["localhost", "127.0.0.1"]);
  },
  "tenant can disable the cache and replace host list": () => {
    const cfg = resolveConfig({ cache: null, allowedHosts: ["tenant.example"] });
    assert.strictEqual(cfg.cache, null);
    assert.deepStrictEqual(cfg.allowedHosts, ["tenant.example"]);
  },
  "merging untrusted JSON cannot pollute Object.prototype": () => {
    const evil = JSON.parse('{"__proto__": {"polluted": "yes"}, "safe": 1}');
    try {
      const out = deepMerge({}, evil);
      assert.strictEqual({}.polluted, undefined, "Object.prototype was polluted");
      assert.strictEqual(out.safe, 1);
    } finally {
      delete Object.prototype.polluted;
    }
  },
};

solution.merge.js:
function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

function clone(v) {
  if (Array.isArray(v)) return v.map(clone);
  if (isPlainObject(v)) {
    const out = {};
    for (const key of Object.keys(v)) {
      if (key === "__proto__") continue;
      out[key] = clone(v[key]);
    }
    return out;
  }
  return v;
}

function deepMerge(...objects) {
  const result = {};
  for (const src of objects) {
    for (const key of Object.keys(src)) {
      if (key === "__proto__" || key === "constructor" || key === "prototype") continue;
      if (isPlainObject(result[key]) && isPlainObject(src[key])) {
        result[key] = deepMerge(result[key], src[key]);
      } else {
        result[key] = clone(src[key]);
      }
    }
  }
  return result;
}

module.exports = { deepMerge, isObject: isPlainObject };

files.diff.js:
function isObj(v) {
  return typeof v === "object";
}

function join(path, key) {
  return path ? path + "." + key : String(key);
}

function diff(a, b, path = "") {
  if (a === b) return [];
  if (isObj(a) && isObj(b) && Array.isArray(a) === Array.isArray(b)) {
    const changes = [];
    for (const key of Object.keys(b)) {
      const p = join(path, key);
      if (!(key in a)) {
        changes.push({ op: "add", path: p, value: b[key] });
      } else {
        changes.push(...diff(a[key], b[key], p));
      }
    }
    for (const key of Object.keys(a)) {
      if (!(key in b)) {
        changes.push({ op: "remove", path: join(path, key) });
      }
    }
    return changes;
  }
  return [{ op: "replace", path, from: a, to: b }];
}

module.exports = { diff };

files.report.js:
function describe(change) {
  switch (change.op) {
    case "add":
      return "+ " + change.path + " = " + JSON.stringify(change.value);
    case "remove":
      return "- " + change.path;
    default:
      return "~ " + change.path + ": " + JSON.stringify(change.from) + " -> " + JSON.stringify(change.to);
  }
}

function report(changes) {
  if (changes.length === 0) return "no changes";
  return changes.map(describe).join("\n");
}

module.exports = { describe, report };

