const { report } = require("./report.js");

const byPath = (list) => [...list].sort((x, y) => (x.path < y.path ? -1 : x.path > y.path ? 1 : 0));

module.exports = {
  "identical documents have no changes": () => {
    const doc = { a: 1, b: { c: [1, 2, { d: "x" }] } };
    assert.deepStrictEqual(diff(doc, JSON.parse(JSON.stringify(doc))), []);
  },
  "replaced nested value": () => {
    assert.deepStrictEqual(diff({ a: { b: 1 } }, { a: { b: 2 } }), [{ op: "replace", path: "a.b", from: 1, to: 2 }]);
  },
  "added and removed keys": () => {
    const out = byPath(diff({ keep: 1, gone: 2 }, { keep: 1, fresh: 3 }));
    assert.deepStrictEqual(out, [
      { op: "add", path: "fresh", value: 3 },
      { op: "remove", path: "gone" },
    ]);
  },
  "null to object is a replace, not a crash": () => {
    assert.deepStrictEqual(diff({ a: null }, { a: { x: 1 } }), [{ op: "replace", path: "a", from: null, to: { x: 1 } }]);
  },
  "object to null is a replace": () => {
    assert.deepStrictEqual(diff({ a: { x: 1 } }, { a: null }), [{ op: "replace", path: "a", from: { x: 1 }, to: null }]);
  },
  "NaN equals NaN": () => {
    assert.deepStrictEqual(diff({ n: NaN, m: 1 }, { n: NaN, m: 2 }), [{ op: "replace", path: "m", from: 1, to: 2 }],
      "NaN to NaN should not be reported as a change");
  },
  "keys named like Object.prototype members are plain keys": () => {
    const out = diff({}, { toString: 1, constructor: 2 });
    assert.deepStrictEqual(byPath(out), [
      { op: "add", path: "constructor", value: 2 },
      { op: "add", path: "toString", value: 1 },
    ]);
  },
  "arrays are compared by index": () => {
    const out = byPath(diff({ l: [1, 2, 3] }, { l: [1, 5] }));
    assert.deepStrictEqual(out, [
      { op: "remove", path: "l.2" },
      { op: "replace", path: "l.1", from: 2, to: 5 },
    ].sort((x, y) => (x.path < y.path ? -1 : 1)));
  },
  "array versus object is a replace": () => {
    assert.strictEqual(diff({ a: [] }, { a: {} })[0].op, "replace");
  },
  "report renders changes": () => {
    const text = report(diff({ a: 1, b: 2 }, { a: 2, c: 3 }));
    assert.deepStrictEqual(text.split("\n").sort(), ["+ c = 3", "- b", "~ a: 1 -> 2"].sort());
    assert.strictEqual(report([]), "no changes");
  },
};

solution.diff.js:
const hasOwn = (o, k) => Object.prototype.hasOwnProperty.call(o, k);

function isObj(v) {
  return v !== null && typeof v === "object";
}

function same(a, b) {
  return a === b || (Number.isNaN(a) && Number.isNaN(b));
}

function join(path, key) {
  return path ? path + "." + key : String(key);
}

function diff(a, b, path = "") {
  if (same(a, b)) return [];
  if (isObj(a) && isObj(b) && Array.isArray(a) === Array.isArray(b)) {
    const changes = [];
    for (const key of Object.keys(b)) {
      const p = join(path, key);
      if (!hasOwn(a, key)) {
        changes.push({ op: "add", path: p, value: b[key] });
      } else {
        changes.push(...diff(a[key], b[key], p));
      }
    }
    for (const key of Object.keys(a)) {
      if (!hasOwn(b, key)) {
        changes.push({ op: "remove", path: join(path, key) });
      }
    }
    return changes;
  }
  return [{ op: "replace", path, from: a, to: b }];
}

module.exports = { diff };

