class TokenBucket {
  constructor({ capacity, refillPerSec, now = Date.now }) {
    this.capacity = capacity;
    this.refillPerSec = refillPerSec;
    this.now = now;
    this.buckets = new Map();
  }

  _bucket(key) {
    const t = this.now();
    let b = this.buckets.get(key);
    if (!b) {
      b = { tokens: this.capacity, last: t };
      this.buckets.set(key, b);
      return b;
    }
    const elapsedSec = (t - b.last) / 1000;
    b.tokens = Math.floor(b.tokens + elapsedSec * this.refillPerSec);
    b.last = t;
    return b;
  }

  tryTake(key, cost = 1) {
    const b = this._bucket(key);
    if (b.tokens >= cost) {
      b.tokens -= cost;
      return true;
    }
    return false;
  }

  retryAfterMs(key, cost = 1) {
    const b = this._bucket(key);
    if (b.tokens >= cost) return 0;
    return Math.ceil((cost - b.tokens) / this.refillPerSec);
  }
}

module.exports = { TokenBucket };

files.guard.js:
function check(bucket, key, cost = 1) {
  if (bucket.tryTake(key, cost)) {
    return { status: 200, headers: {} };
  }
  const ms = bucket.retryAfterMs(key, cost);
  return { status: 429, headers: { "Retry-After": String(Math.ceil(ms / 1000)) } };
}

module.exports = { check };

