const assert = require("assert");
const { TokenBucket } = require("./bucket.js");
const { check } = require("./guard.js");

function make(opts) {
  const clock = { t: 0 };
  const bucket = new TokenBucket({ now: () => clock.t, ...opts });
  return { clock, bucket };
}

module.exports = {
  "starts full and allows a burst up to capacity": () => {
    const { bucket } = make({ capacity: 3, refillPerSec: 1 });
    const results = [1, 2, 3, 4].map(() => bucket.tryTake("c"));
    assert.deepStrictEqual(results, [true, true, true, false]);
  },
  "refills over time": () => {
    const { clock, bucket } = make({ capacity: 2, refillPerSec: 1 });
    bucket.tryTake("c");
    bucket.tryTake("c");
    assert.strictEqual(bucket.tryTake("c"), false);
    clock.t = 1000;
    assert.strictEqual(bucket.tryTake("c"), true);
    assert.strictEqual(bucket.tryTake("c"), false);
  },
  "fractional refill accumulates across frequent polls": () => {
    const { clock, bucket } = make({ capacity: 2, refillPerSec: 1 });
    bucket.tryTake("c");
    bucket.tryTake("c");
    const results = [];
    for (const t of [400, 800, 1200]) {
      clock.t = t;
      results.push(bucket.tryTake("c"));
    }
    assert.deepStrictEqual(results, [false, false, true], "polling every 400ms should succeed at 1200ms, got " + JSON.stringify(results));
  },
  "idle time never exceeds capacity": () => {
    const { clock, bucket } = make({ capacity: 3, refillPerSec: 1 });
    bucket.tryTake("c");
    clock.t = 100000;
    const results = [1, 2, 3, 4, 5].map(() => bucket.tryTake("c"));
    assert.deepStrictEqual(results, [true, true, true, false, false], "tokens grew past capacity");
  },
  "keys have independent buckets": () => {
    const { bucket } = make({ capacity: 1, refillPerSec: 1 });
    assert.strictEqual(bucket.tryTake("a"), true);
    assert.strictEqual(bucket.tryTake("a"), false);
    assert.strictEqual(bucket.tryTake("b"), true);
  },
  "retryAfterMs is reported in milliseconds": () => {
    const { bucket } = make({ capacity: 1, refillPerSec: 0.4 });
    bucket.tryTake("c");
    assert.strictEqual(bucket.retryAfterMs("c"), 2500);
  },
  "retryAfterMs shrinks as time passes and is 0 when allowed": () => {
    const { clock, bucket } = make({ capacity: 1, refillPerSec: 1 });
    assert.strictEqual(bucket.retryAfterMs("c"), 0);
    bucket.tryTake("c");
    clock.t = 250;
    assert.strictEqual(bucket.retryAfterMs("c"), 750);
  },
  "guard returns 200 or 429 with Retry-After in seconds": () => {
    const { bucket } = make({ capacity: 1, refillPerSec: 0.4 });
    assert.strictEqual(check(bucket, "c").status, 200);
    const denied = check(bucket, "c");
    assert.strictEqual(denied.status, 429);
    assert.strictEqual(denied.headers["Retry-After"], "3", "2.5 s should round up to 3, got " + denied.headers["Retry-After"]);
  },
};

