const { BatchLoader } = require("./loader.js");

function createUserService({ fetchUsers }) {
  const loader = new BatchLoader(async (ids) => {
    const rows = await fetchUsers(ids);
    const byId = new Map(rows.map((u) => [u.id, u]));
    return ids.map((id) => byId.get(id) || new Error("user " + id + " not found"));
  });

  return {
    getUser: (id) => loader.load(id),
    getUsers: (ids) => loader.loadMany(ids),
    invalidate: (id) => loader.clear(id),
  };
}

module.exports = { createUserService };

