const assert = require("assert");
const { BatchLoader } = require("./loader.js");
const { createUserService } = require("./users.js");

const tick = () => new Promise((r) => setTimeout(r, 1));

function spy(fn) {
  const calls = [];
  const wrapped = async (keys) => {
    calls.push([...keys]);
    return fn(keys);
  };
  wrapped.calls = calls;
  return wrapped;
}

module.exports = {
  "loads in the same tick are one batch": async () => {
    const fn = spy((keys) => keys.map((k) => k * 10));
    const loader = new BatchLoader(fn);
    const out = await Promise.all([loader.load(1), loader.load(2), loader.load(3)]);
    assert.deepStrictEqual(out, [10, 20, 30]);
    assert.deepStrictEqual(fn.calls, [[1, 2, 3]]);
  },
  "duplicate keys in one tick are fetched once": async () => {
    const fn = spy((keys) => keys.map((k) => k * 10));
    const loader = new BatchLoader(fn);
    const out = await Promise.all([loader.load(7), loader.load(7), loader.load(8)]);
    assert.deepStrictEqual(out, [70, 70, 80]);
    assert.deepStrictEqual(fn.calls, [[7, 8]], "batch keys were " + JSON.stringify(fn.calls));
  },
  "results are cached across batches": async () => {
    const fn = spy((keys) => keys.map((k) => k + 1));
    const loader = new BatchLoader(fn);
    await loader.load(1);
    await tick();
    assert.strictEqual(await loader.load(1), 2);
    assert.strictEqual(fn.calls.length, 1);
  },
  "loadMany works and preserves order": async () => {
    const fn = spy((keys) => keys.map((k) => "v" + k));
    const loader = new BatchLoader(fn);
    assert.deepStrictEqual(await loader.loadMany([3, 1, 2]), ["v3", "v1", "v2"]);
    assert.deepStrictEqual(fn.calls, [[3, 1, 2]]);
  },
  "maxBatch splits large batches": async () => {
    const fn = spy((keys) => keys);
    const loader = new BatchLoader(fn, { maxBatch: 2 });
    await loader.loadMany([1, 2, 3, 4, 5]);
    assert.deepStrictEqual(fn.calls.map((c) => c.length), [2, 2, 1]);
  },
  "an Error entry rejects only that key": async () => {
    const loader = new BatchLoader(async (keys) => keys.map((k) => (k === 2 ? new Error("missing 2") : k)));
    const [a, b] = await Promise.allSettled([loader.load(1), loader.load(2)]);
    assert.strictEqual(a.status, "fulfilled");
    assert.strictEqual(a.value, 1);
    assert.strictEqual(b.status, "rejected", "an Error value must reject, not resolve");
    assert.strictEqual(b.reason.message, "missing 2");
  },
  "a failed key is not cached and can be retried": async () => {
    let attempt = 0;
    const loader = new BatchLoader(async (keys) => {
      attempt++;
      return keys.map((k) => (attempt === 1 ? new Error("flaky") : "ok" + k));
    });
    await assert.rejects(() => loader.load(5), /flaky/);
    await tick();
    assert.strictEqual(await loader.load(5), "ok5", "failed lookups must be evicted from the cache");
  },
  "a whole-batch failure rejects every key and can be retried": async () => {
    let fail = true;
    const loader = new BatchLoader(async (keys) => {
      if (fail) throw new Error("db down");
      return keys;
    });
    const results = await Promise.allSettled([loader.load(1), loader.load(2)]);
    assert.deepStrictEqual(results.map((r) => r.status), ["rejected", "rejected"]);
    fail = false;
    await tick();
    assert.strictEqual(await loader.load(1), 1);
  },
  "keys requested while a batch is running form the next batch": async () => {
    let late;
    const fn = spy(async (keys) => {
      if (keys[0] === "first") late = loader.load("late");
      await tick();
      return keys.map((k) => k.toUpperCase());
    });
    const loader = new BatchLoader(fn);
    assert.strictEqual(await loader.load("first"), "FIRST");
    assert.strictEqual(await late, "LATE");
    assert.deepStrictEqual(fn.calls, [["first"], ["late"]]);
  },
  "user service maps unordered rows and reports missing users": async () => {
    const seen = [];
    const svc = createUserService({
      fetchUsers: async (ids) => {
        seen.push(ids);
        return [{ id: 8, name: "Ben" }, { id: 7, name: "Ann" }];
      },
    });
    const [u7, u8] = await svc.getUsers([7, 8]);
    assert.strictEqual(u7.name, "Ann");
    assert.strictEqual(u8.name, "Ben");
    await assert.rejects(() => svc.getUser(9), /user 9 not found/);
    assert.deepStrictEqual(seen, [[7, 8], [9]]);
  },
};

solution.loader.js:
// Collects load(key) calls made in the same tick and resolves them with one
// batchFn(keys) call. batchFn must return an array with one entry per key, in
// the same order. An entry that is an Error instance rejects only that key.
class BatchLoader {
  constructor(batchFn, { maxBatch = 100 } = {}) {
    this.batchFn = batchFn;
    this.maxBatch = maxBatch;
    this.cache = new Map();
    this.queue = [];
    this.scheduled = false;
  }

  load(key) {
    if (this.cache.has(key)) return this.cache.get(key);
    const promise = new Promise((resolve, reject) => {
      this.queue.push({ key, resolve, reject });
    });
    this.cache.set(key, promise);
    if (!this.scheduled) {
      this.scheduled = true;
      Promise.resolve().then(() => this._dispatch());
    }
    return promise;
  }

  loadMany(keys) {
    return Promise.all(keys.map((key) => this.load(key)));
  }

  clear(key) {
    this.cache.delete(key);
  }

  async _dispatch() {
    const batch = this.queue;
    this.queue = [];
    this.scheduled = false;
    for (let i = 0; i < batch.length; i += this.maxBatch) {
      const chunk = batch.slice(i, i + this.maxBatch);
      const keys = chunk.map((job) => job.key);
      let values;
      try {
        values = await this.batchFn(keys);
        if (!Array.isArray(values) || values.length !== keys.length) {
          throw new Error("batchFn must return one value per key");
        }
      } catch (err) {
        chunk.forEach((job) => {
          this.cache.delete(job.key);
          job.reject(err);
        });
        continue;
      }
      chunk.forEach((job, idx) => {
        const value = values[idx];
        if (value instanceof Error) {
          this.cache.delete(job.key);
          job.reject(value);
        } else {
          job.resolve(value);
        }
      });
    }
  }
}

module.exports = { BatchLoader };
